class Solution { public: char slowestKey(vector<int>& releaseTimes,string keysPressed){int previous=0,bestDuration=0;char answer='a';for(int i=0;i<(int)releaseTimes.size();++i){int duration=releaseTimes[i]-previous;char key=keysPressed[i];if(duration>bestDuration||(duration==bestDuration&&key>answer)){bestDuration=duration;answer=key;}previous=releaseTimes[i];}return answer;} };
